<section class="section"><div class="eyebrow">جستجوی جهانی</div><h1>نتایج جستجو</h1><form class="site-search" method="get" action="<?=url('/search')?>"><input name="q" value="<?=e($q)?>" required placeholder="پروژه، مهارت یا نام فریلنسر..."><select name="type"><option value="all" <?= $type==='all'?'selected':''?>>همه</option><option value="jobs" <?= $type==='jobs'?'selected':''?>>پروژه‌ها</option><option value="freelancers" <?= $type==='freelancers'?'selected':''?>>فریلنسرها</option></select><button class="button">جستجو</button></form><?php if($q===''):?><div class="empty-state">عبارت جستجو را وارد کنید.</div><?php else:?><div class="search-columns"><section><h2>پروژه‌ها</h2><?php foreach($jobs as $job):?><article class="job-item public-card"><h3><?=e($job['title'])?></h3><p><?=e($job['description'])?></p><small><?=e($job['employer_name']?:'کارفرما')?> · <?=e($job['budget_min'])?> تا <?=e($job['budget_max'])?> دلار</small></article><?php endforeach;?><?php if(!$jobs):?><p class="muted">پروژه‌ای پیدا نشد.</p><?php endif;?></section><section><h2>فریلنسرها</h2><?php foreach($freelancers as $f):?><a class="freelancer-item public-card" href="<?=url('/freelancer?username='.rawurlencode($f['username']))?>"><h3><?=e($f['display_name'])?></h3><p><?=e($f['headline']?:'متخصص مستقل')?></p><small><?=e($f['hourly_rate']?:'—')?> دلار/ساعت</small></a><?php endforeach;?><?php if(!$freelancers):?><p class="muted">فریلنسر دیگری پیدا نشد.</p><?php endif;?></section></div><?php endif;?></section>